// Executes the portable SIMD instructions generated by test_simd.py.
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#ifdef _WIN32
#include <windows.h>
#else
#include <sys/mman.h>
#endif

#include "cpu.h"

#define CODE 0x7210000000ull
#define BUF 0x7200000000ull
#define BUF_SIZE 0x20000u

extern GuestFn tests[];
extern int ntests;

typedef struct {
    uint64_t index, fpcr, x[32], sp, nzcv;
    __uint128_t v[32];
    uint64_t store, reserved;
} Input;

typedef struct {
    uint64_t x[31], sp, nzcv, memory_crc;
    __uint128_t v[32];
} Output;

_Static_assert(sizeof(Input) == 816, "test_simd.py input record");
_Static_assert(sizeof(Output) == 784, "test_simd.py output record");

void rt_dispatch(Cpu *cpu) { (void)cpu; abort(); }
void rt_svc(Cpu *cpu, uint32_t imm, uint64_t pc) { (void)cpu; (void)imm; (void)pc; abort(); }
void rt_brk(Cpu *cpu, uint32_t imm, uint64_t pc) { (void)cpu; (void)imm; (void)pc; abort(); }
void rt_udf(Cpu *cpu, uint64_t pc) { (void)cpu; (void)pc; abort(); }
void rt_trust_fault(Cpu *cpu, uint64_t pc) { (void)cpu; (void)pc; abort(); }
uint64_t rt_ticks(void) { return 0; }

static void *map_file(const char *path, uintptr_t address, size_t expected_size) {
    FILE *file = fopen(path, "rb");
    if (!file || fseek(file, 0, SEEK_END)) { perror(path); exit(1); }
    long size = ftell(file);
    if (size <= 0 || (expected_size && size != (long)expected_size) || fseek(file, 0, SEEK_SET)) {
        fprintf(stderr, "%s: invalid fixture length\n", path);
        exit(1);
    }
#ifdef _WIN32
    void *data = VirtualAlloc((void *)address, (size_t)size, MEM_RESERVE | MEM_COMMIT, PAGE_READWRITE);
#else
    void *data = mmap((void *)address, (size_t)size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
#endif
    if (data != (void *)address || fread(data, 1, (size_t)size, file) != (size_t)size || fclose(file)) {
        fprintf(stderr, "%s: could not load fixture at %llx\n", path, (unsigned long long)address);
        exit(1);
    }
    return data;
}

static uint32_t crc_table[256];

static void init_crc(void) {
    for (unsigned i = 0; i < 256; i++) {
        uint32_t crc = i;
        for (int bit = 0; bit < 8; bit++) crc = (crc >> 1) ^ ((crc & 1) ? 0xedb88320u : 0);
        crc_table[i] = crc;
    }
}

static uint32_t memory_crc(const uint8_t *bytes) {
    uint32_t crc = UINT32_MAX;
    for (size_t i = 0; i < BUF_SIZE; i++) crc = (crc >> 8) ^ crc_table[(crc ^ bytes[i]) & 255];
    return ~crc;
}

int main(int argc, char **argv) {
    if (argc != 5) return 2;
    map_file(argv[1], CODE, 0);
    void *memory = map_file(argv[2], BUF, BUF_SIZE);
    static uint8_t pristine[BUF_SIZE];
    memcpy(pristine, memory, BUF_SIZE);
    init_crc();

    FILE *cases = fopen(argv[3], "rb");
    FILE *results = fopen(argv[4], "wb");
    if (!cases || !results) { perror("opening SIMD input or output"); return 1; }
    Input input;
    size_t size;
    while ((size = fread(&input, 1, sizeof input, cases)) == sizeof input) {
        if (input.index >= (uint64_t)ntests) return 1;
        Cpu cpu = {0};
        memcpy(cpu.x, input.x, sizeof cpu.x);
        memcpy(cpu.v, input.v, sizeof cpu.v);
        cpu.sp = input.sp;
        cpu.pc = CODE + 4 * input.index;
        cpu.nzcv = input.nzcv;
        cpu.fpcr = input.fpcr;
        cpu.excl_addr = UINT64_MAX;
        tests[input.index](&cpu);
        Output output = {.sp = cpu.sp, .nzcv = cpu.nzcv & 0xf0000000u};
        memcpy(output.x, cpu.x, sizeof output.x);
        memcpy(output.v, cpu.v, sizeof output.v);
        if (input.store) {
            output.memory_crc = memory_crc(memory);
            memcpy(memory, pristine, BUF_SIZE);
        }
        if (fwrite(&output, sizeof output, 1, results) != 1) return 1;
    }
    int failed = size != 0 || ferror(cases);
    if (fclose(cases)) failed = 1;
    if (fclose(results)) failed = 1;
    return failed;
}
